func TestKeySortsByAFieldNumerically(t *testing.T) {
	in := "root:x:0:0\nbob:x:1000:1000\nbin:x:2:2\nzed:x:10:10\n"
	want := "root:x:0:0\nbin:x:2:2\nzed:x:10:10\nbob:x:1000:1000\n"
	if got := sorted(t, in, "-t:", "-k3,3n"); got != want {
		t.Errorf("sort -t: -k3,3n = %q, want %q", got, want)
	}
}

func TestLaterKeysBreakTies(t *testing.T) {
	in := "a:2:x\nb:1:y\nc:2:a\nd:1:z\n"
	want := "d:1:z\nb:1:y\nc:2:a\na:2:x\n"
	if got := sorted(t, in, "-t:", "-k2,2n", "-k3,3r"); got != want {
		t.Errorf("sort -t: -k2,2n -k3,3r = %q, want %q", got, want)
	}
}

func TestKeyWithoutEndRunsToEndOfLine(t *testing.T) {
	// -k2 compares "b:2" with "b:1"; -k2,2 ties on "b" and falls back to
	// the whole line.
	in := "z:b:1\na:b:2\n"
	if got := sorted(t, in, "-t:", "-k2"); got != "z:b:1\na:b:2\n" {
		t.Errorf("sort -t: -k2 = %q", got)
	}
	if got := sorted(t, in, "-t:", "-k2,2"); got != "a:b:2\nz:b:1\n" {
		t.Errorf("sort -t: -k2,2 = %q", got)
	}
}

func TestDefaultFieldsKeepTheirLeadingBlanks(t *testing.T) {
	// Without -t the second field of "x  b" is "  b", which sorts before
	// " a"; b skips the blanks.
	in := "y a\nx  b\n"
	if got := sorted(t, in, "-k2"); got != "x  b\ny a\n" {
		t.Errorf("sort -k2 = %q", got)
	}
	if got := sorted(t, in, "-k2b"); got != "y a\nx  b\n" {
		t.Errorf("sort -k2b = %q", got)
	}
}

func TestCharacterPositions(t *testing.T) {
	in := "x:ab9\nx:cd1\n"
	if got := sorted(t, in, "-t:", "-k2.3,2.3"); got != "x:cd1\nx:ab9\n" {
		t.Errorf("sort -t: -k2.3,2.3 = %q", got)
	}
}

func TestPlainKeysTakeTheGlobalOptions(t *testing.T) {
	in := "a 10\nb 9\n"
	if got := sorted(t, in, "-n", "-k2"); got != "b 9\na 10\n" {
		t.Errorf("sort -n -k2 = %q", got)
	}
	// A key with options of its own does not take the global ones, but -r
	// still reverses the last-resort comparison.
	if got := sorted(t, "b 1\na 1\n", "-r", "-k2n"); got != "b 1\na 1\n" {
		t.Errorf("sort -r -k2n = %q", got)
	}
}

func TestBadKeysAndTabs(t *testing.T) {
	for _, c := range []struct {
		args []string
		want string
	}{
		{[]string{"-k0"}, "sort: field number is zero: invalid field specification '0'\n"},
		{[]string{"-k1.0"}, "sort: character offset is zero: invalid field specification '1.0'\n"},
		{[]string{"-k2,x"}, "sort: invalid number after ',': invalid count at start of 'x'\n"},
		{[]string{"-k2y"}, "sort: stray character in field spec: invalid field specification '2y'\n"},
