		var out, errOut bytes.Buffer
		code := run(c.args, strings.NewReader("a\n"), &out, &errOut)
		if code != 2 || out.Len() != 0 || errOut.String() != c.want {
			t.Errorf("sort %q: exit %d, stdout %q, stderr %q; want exit 2, %q", c.args, code, out.String(), errOut.String(), c.want)
		}
	}
}
