}

func TestNamedFilesAreReadInOrder(t *testing.T) {
	dir := t.TempDir()
	a, b := filepath.Join(dir, "a"), filepath.Join(dir, "b")
	os.WriteFile(a, []byte("first\n"), 0o644)
	os.WriteFile(b, []byte("second\n"), 0o644)
