				case value < initial:
					return nil, errors.New("invalid decreasing range")
				default:
					l = append(l, span{clamp(initial), clamp(value)})
				}
			} else {
				if value == 0 {
					return nil, errors.New(w.zero)
				}
				l = append(l, span{clamp(value), clamp(value)})
			}
			value = 0
			if i == len(s) {
				return l, nil
			}
			lhs, rhs = false, false
