func TestUniqueKeepsTheFirstOfEqualLines(t *testing.T) {
	// GNU coreutils 9.4, LC_ALL=C.
	for _, c := range []struct {
		in   string
		args []string
		want string
	}{
		// Equal as numbers is equal: the first of 1 and 01 stays.
		{"1\n01\n", []string{"-nu"}, "1\n"},
		{"01\n1\n2\n", []string{"--numeric-sort", "--unique"}, "01\n2\n"},
		// Without -n only identical lines are equal.
		{"b\na\nb\n01\n1\n", []string{"-u"}, "01\n1\na\nb\n"},
		// With keys, only the keys count.
		{"x:1:p\ny:1:q\nz:2:p\n", []string{"-t:", "-k2,2n", "-u"}, "x:1:p\nz:2:p\n"},
		{"x:1:p\ny:1:q\nz:2:p\n", []string{"-t:", "-k2,2n", "-ru"}, "z:2:p\nx:1:p\n"},
	} {
		if got := sorted(t, c.in, c.args...); got != c.want {
			t.Errorf("sort %q on %q = %q, want %q", c.args, c.in, got, c.want)
		}
	}
}

func TestStableKeepsTiedLinesInInputOrder(t *testing.T) {
	// The keys tie, so the lines stay as given rather than by bytes.
	in := "b:1\na:1\nc:0\n"
	if got := sorted(t, in, "-t:", "-k2,2n", "-s"); got != "c:0\nb:1\na:1\n" {
		t.Errorf("sort -s = %q", got)
	}
	if got := sorted(t, in, "-t:", "-k2,2n"); got != "c:0\na:1\nb:1\n" {
		t.Errorf("sort without -s = %q, want the tie broken by bytes", got)
	}
	// -r reverses the keys but not the input order of ties.
	if got := sorted(t, in, "-t:", "-k2,2n", "--stable", "-r"); got != "b:1\na:1\nc:0\n" {
		t.Errorf("sort -sr = %q", got)
	}
}
