// fields cuts one line: the selected fields, each once and in the order
// they stand in the line whatever order the list names them in, joined by
// the delimiter. A line without the delimiter is printed whole.
func fields(line []byte, delim byte, l list) []byte {
	if bytes.IndexByte(line, delim) < 0 {
		return line
	}
	var out [][]byte
	for i, f := range bytes.Split(line, []byte{delim}) {
		if l.has(i + 1) {
			out = append(out, f)
		}
	}
	return bytes.Join(out, []byte{delim})
}

// positions cuts one line by bytes: the selected bytes, each once and in
// line order. In the C locale a character is a byte, so -c cuts the same.
func positions(line []byte, l list) []byte {
	var out []byte
	for i, b := range line {
		if l.has(i + 1) {
			out = append(out, b)
		}
	}
	return out
}

// config reads the options: one list, of fields, bytes or characters,
// which must be given, and the delimiter, a single byte, a tab when none
// is given, only for fields. As in GNU, the list is checked last.
func config(given []opts.Opt) (cutter func([]byte) []byte, err error) {
	delim := byte('\t')
	delimGiven := false
	var mode byte
	var spec string
	for _, o := range given {
		switch o.Name {
		case 'd':
			if len(o.Value) != 1 {
				return nil, errors.New("the delimiter must be a single character")
			}
			delim, delimGiven = o.Value[0], true
		case 'b', 'c', 'f':
			if mode != 0 {
				return nil, errors.New("only one list may be specified")
			}
			mode, spec = o.Name, o.Value
		}
	}
	if mode == 0 {
		return nil, errors.New("you must specify a list of bytes, characters, or fields")
	}
	if delimGiven && mode != 'f' {
		return nil, errors.New("an input delimiter may be specified only when operating on fields")
	}
	if mode == 'f' {
		l, err := parseList(spec, fieldWords)
		if err != nil {
			return nil, err
		}
		return func(line []byte) []byte { return fields(line, delim, l) }, nil
	}
	l, err := parseList(spec, positionWords)
	if err != nil {
		return nil, err
	}
	return func(line []byte) []byte { return positions(line, l) }, nil
}

func run(args []string, stdin io.Reader, stdout, stderr io.Writer) int {
	given, names, err := opts.Parse(args, spec)
	if err == nil {
		var cutter func([]byte) []byte
		if cutter, err = config(given); err == nil {
			srcs, err := input.Read(names, stdin)
			for _, s := range srcs {
				for _, ln := range input.Lines(s.Data) {
					stdout.Write(append(cutter(ln), '\n'))
				}
			}
			if err != nil {
				fmt.Fprintf(stderr, "cut: %v\n", err)
				return 1
			}
			return 0
		}
	}
	fmt.Fprintf(stderr, "cut: %v\nTry 'cut --help' for more information.\n", err)
	return 1
}

