func TestComplementAndOutputDelimiter(t *testing.T) {
	// GNU coreutils 9.4, LC_ALL=C.
	for _, c := range []struct {
		in   string
		args []string
		want string
	}{
		{"a:b:c:d\n", []string{"-d:", "-f2", "--complement"}, "a:c:d\n"},
		{"a:b:c:d\n", []string{"-d:", "-f1,3", "--output-delimiter=--"}, "a--c\n"},
		{"a:b:c:d\n", []string{"-d:", "-f2-3", "--complement", "--output-delimiter=,"}, "a,d\n"},
		{"plain\n", []string{"-d:", "-f2", "--complement", "--output-delimiter=,"}, "plain\n"},
		{"abcdefgh\n", []string{"-b2-3", "--complement"}, "adefgh\n"},
		{"abcdefgh\n", []string{"-c2-3", "--complement", "--output-delimiter=:"}, "a:defgh\n"},
		// The delimiter falls between ranges, after overlapping ones merge
		// but not touching ones.
		{"abcdefgh\n", []string{"-b1-3,2-5,7", "--output-delimiter=:"}, "abcde:g\n"},
		{"abcdefgh\n", []string{"-b1-2,3-4", "--output-delimiter=:"}, "ab:cd\n"},
		{"abcdefgh\n", []string{"-b3,1", "--output-delimiter=:"}, "a:c\n"},
		{"abcdefgh\n", []string{"-b1-", "--complement"}, "\n"},
		// An empty output delimiter is the NUL byte.
		{"abcd\n", []string{"-b2,4", "--output-delimiter="}, "b\x00d\n"},
	} {
		if got := cutOK(t, c.in, c.args...); got != c.want {
			t.Errorf("cut %q on %q = %q, want %q", c.args, c.in, got, c.want)
		}
	}
}

func TestLongOnlyOptionsAreNotShort(t *testing.T) {
	out, stderr, code := cut(t, nil, "abc\n", "-b1", "--complement=1")
	if code != 1 || out != "" || !strings.Contains(stderr, "option '--complement' doesn't allow an argument") {
		t.Errorf("cut --complement=1: exit %d, stdout %q, stderr %q", code, out, stderr)
	}
}
