func TestSkipFieldsAndChars(t *testing.T) {
	// GNU coreutils 9.4, LC_ALL=C. Log lines whose timestamps differ.
	logs := "2026-11-26 10:00:01 disk full\n" +
		"2026-11-26 10:00:02 disk full\n" +
		"2026-11-26 10:00:05 disk  full\n" +
		"2026-11-26 10:00:07 login ok\n"
	for _, c := range []struct {
		in   string
		args []string
		want string
	}{
		// The first of each run is printed, its timestamp with it.
		{logs, []string{"-f2"}, "2026-11-26 10:00:01 disk full\n2026-11-26 10:00:05 disk  full\n2026-11-26 10:00:07 login ok\n"},
		{logs, []string{"-c", "--skip-fields=2"}, "      2 2026-11-26 10:00:01 disk full\n      1 2026-11-26 10:00:05 disk  full\n      1 2026-11-26 10:00:07 login ok\n"},
		// A skipped field takes the blanks before it, not after.
		{"a x\nb  x\n", []string{"-f1"}, "a x\nb  x\n"},
		{"a x\nb  x\n", []string{"-f1", "-s1"}, "a x\nb  x\n"},
		{"a x\nb  x\n", []string{"-f1", "-s2"}, "a x\n"},
		// Bytes skip after fields; -s alone skips from the start.
		{"10 ok\n20 ok\n", []string{"-s2"}, "10 ok\n"},
		{"10 ok\n20 ok\n", []string{"--skip-chars=1"}, "10 ok\n20 ok\n"},
		// Only spaces and tabs separate fields.
		{"a\vx\na\vy\n", []string{"-f1"}, "a\vx\n"},
		{"a\tx\nb\tx\n", []string{"-f1", "-d"}, "a\tx\n"},
		// Skipping past the end leaves nothing, which compares equal.
		{"a\nb\n", []string{"-f99999999999999999999"}, "a\n"},
		{"ab x\ncd X\n", []string{"-f1", "-i"}, "ab x\n"},
	} {
		if got, stderr, code := uniq(c.in, c.args...); got != c.want || code != 0 {
			t.Errorf("uniq %q = %q (exit %d, %s), want %q", c.args, got, code, stderr, c.want)
		}
	}
}

func TestBadSkipCounts(t *testing.T) {
	for _, c := range []struct {
		args []string
		want string
	}{
		{[]string{"-fx"}, "uniq: x: invalid number of fields to skip\n"},
		{[]string{"-f-0"}, "uniq: -0: invalid number of fields to skip\n"},
		{[]string{"--skip-chars=1x"}, "uniq: 1x: invalid number of bytes to skip\n"},
	} {
		out, stderr, code := uniq("a\n", c.args...)
		if code != 1 || out != "" || stderr != c.want {
			t.Errorf("uniq %q: exit %d, stdout %q, stderr %q; want exit 1, %q", c.args, code, out, stderr, c.want)
		}
	}
}
