func TestMaxLineLength(t *testing.T) {
	// GNU coreutils 9.4, LC_ALL=C: printf ... | wc -L
	for in, want := range map[string]string{
		"abc\n":          "3\n",
		"a\tb\n":         "9\n",  // the tab runs to column 8
		"abcdefgh\tx\n":  "17\n", // a tab at a multiple of 8 runs to the next
		"ab\rcdefg\n":    "5\n",  // a carriage return starts again
		"abc\fd\n":       "3\n",  // as does a form feed
		"a\vb\x01c\n":    "3\n",  // controls have no width
		"a\xc3\xa9b\n":   "2\n",  // nor do bytes past ASCII
		"abcd":           "4\n",  // the last line needs no newline
		"short\nlonger\n": "6\n",
	} {
		if got := counted(t, nil, in, "-L"); got != want {
			t.Errorf("wc -L on %q = %q, want %q", in, got, want)
		}
	}
}

func TestCharsAndTheFixedOrder(t *testing.T) {
	// GNU coreutils 9.4, LC_ALL=C: printf 'a b\nccc\n' | wc -mLclw
	if got := counted(t, nil, "a b\nccc\n", "-mLclw"); got != "      2       3       8       8       3\n" {
		t.Errorf("wc -mLclw = %q", got)
	}
	// Characters are bytes in the C locale.
	if got := counted(t, nil, "\xc3\xa9\n", "--chars"); got != "3\n" {
		t.Errorf("wc --chars on é = %q, want 3", got)
	}
}

func TestTheTotalOfMaxLineLengthIsTheLongest(t *testing.T) {
	// GNU coreutils 9.4, LC_ALL=C: wc -L m1 m2
	files := map[string]string{"m1": "ab\n", "m2": "abcde\n"}
	if got := counted(t, files, "", "--max-line-length", "m1", "m2"); got != "2 m1\n5 m2\n5 total\n" {
		t.Errorf("wc -L m1 m2 = %q", got)
	}
}
EOF
