// Message describes an error reading an input as GNU does: the input's
// name, then the system's description of the error, capitalized.
func Message(err error) string {
	var pe *os.PathError
	if errors.As(err, &pe) {
		err = pe.Err
		for {
			var inner *os.PathError
			if !errors.As(err, &inner) {
				break
			}
			err = inner.Err
		}
		msg := err.Error()
		if msg != "" {
			msg = strings.ToUpper(msg[:1]) + msg[1:]
		}
		return pe.Path + ": " + msg
	}
	return err.Error()
}
