package input

import (
	"fmt"
	"strings"
)

// Quote quotes a file name for an error message as GNU's quotef does in the
// C locale: as is when a shell would read it as it stands, else in shell
// quotes. A name holding a single quote but nothing a shell's double
// quotes would change is double-quoted; any other is single-quoted, with
// each single quote written '\'' and each control or non-ASCII byte in a
// $'...' escape.
func Quote(name string) string {
	if name == "" {
		return "''"
	}
	needs, hasQuote, plain := false, false, true
	for i := 0; i < len(name); i++ {
		c := name[i]
		switch {
		case c == '\'':
			needs, hasQuote = true, true
		case c == ' ' || c == ':':
			needs = true
		case strings.IndexByte("!\"$&()*;<=>?[\\^`|", c) >= 0:
			needs, plain = true, false
		case (c == '#' || c == '~') && i == 0:
			needs = true
		case (c == '{' || c == '}') && len(name) == 1:
			needs, plain = true, false
		case c < 0x20 || c >= 0x7f:
			needs, plain = true, false
		case 'a' <= c && c <= 'z', 'A' <= c && c <= 'Z', '0' <= c && c <= '9',
			strings.IndexByte("%+,-./]_", c) >= 0:
		default:
			plain = false
		}
	}
	switch {
	case !needs:
		return name
	case hasQuote && plain:
		return `"` + name + `"`
	}
	var b strings.Builder
	b.WriteByte('\'')
	inEscape := false
	for i := 0; i < len(name); i++ {
		c := name[i]
		switch {
		case c == '\'':
			b.WriteString(`'\''`)
			inEscape = false
		case c < 0x20 || c >= 0x7f:
			if !inEscape {
				b.WriteString(`'$'`)
				inEscape = true
			}
			b.WriteString(escape(c))
		default:
			if inEscape {
				b.WriteString(`''`)
				inEscape = false
			}
			b.WriteByte(c)
		}
	}
	b.WriteByte('\'')
	return b.String()
}

// QuoteAlways quotes s as GNU's quote does in the C locale: always in
// single quotes, with backslashes and single quotes escaped by a
// backslash and control and non-ASCII bytes written as C escapes.
func QuoteAlways(s string) string {
	var b strings.Builder
	b.WriteByte('\'')
	for i := 0; i < len(s); i++ {
		switch c := s[i]; {
		case c == '\\' || c == '\'':
			b.WriteByte('\\')
			b.WriteByte(c)
		case c < 0x20 || c >= 0x7f:
			b.WriteString(escape(c))
		default:
			b.WriteByte(c)
		}
	}
	b.WriteByte('\'')
	return b.String()
}

// escape writes a control or non-ASCII byte as C does: by its letter when
// it has one, else in three octal digits.
func escape(c byte) string {
	if i := strings.IndexByte("\a\b\f\n\r\t\v", c); i >= 0 {
		return `\` + string("abfnrtv"[i])
	}
	return fmt.Sprintf(`\%03o`, c)
}
